  ('febe07e3-7f78-413b-b401-05731d3e1433', $$Biologie$$, $$VWO$$, $$Gemodificeerde zweepwormen tegen de ziekte van Crohn$$, $$VWO Biologie 2021-III$$);

insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('6d98526f-969c-4966-a8b6-f8773f2679d9', '3e27f270-ac9d-4261-8b68-f5dad72ffde5', $$bouw van een koraaldiertje en symbiose met zoöxanthellen (afbeelding 1)$$,
   $$biologie-vwo-2021-iii-koraalverbleking-context1.png$$,
   $$Koraalriffen worden opgebouwd door kolonievormende koraaldiertjes. De koraaldiertjes hebben een bekervormig uitwendig skelet van kalk (CaCO3), waarmee ze vastgehecht zijn aan elkaar en aan de ondergrond. Het rif groeit doordat de kalkskeletten steeds boven elkaar worden afgezet.
Elk koraaldiertje heeft rondom de mondopening een ring van tentakels met netelcellen, waarmee het plankton en kleine diertjes uit het water vangt. De koraaldiertjes leven bijna allemaal in symbiose met verschillende soorten zoöxanthellen. Deze eencellige algen horen alle tot het geslacht Symbiodinium. Zoöxanthellen leven in cellen van de tentakels van de koraaldiertjes, en produceren daar organische stoffen en zuurstof, die door de koraaldiertjes worden gebruikt.
In afbeelding 1 is de bouw van een koraaldiertje weergegeven.$$, 'inline'),
  ('c489d403-5f48-4a68-ad26-b77eacfaa26e', '3e27f270-ac9d-4261-8b68-f5dad72ffde5', $$koraalriffen komen voor tot een diepte van 50 meter$$,
   $$biologie-vwo-2021-iii-koraalverbleking-context2.png$$,
   $$Koraalriffen komen langs de kusten van tropische oceanen voor, meestal tot een diepte van 50 meter.$$, 'inline'),
  ('c8755f54-b6e1-45c7-98e2-6edd86c11539', '3e27f270-ac9d-4261-8b68-f5dad72ffde5', $$competitief voordeel van zoöxanthellen ten opzichte van vrij levende algen; vier gegevens$$,
   $$biologie-vwo-2021-iii-koraalverbleking-context3.png$$,
   $$Het water rond de koraalriffen is arm aan voedingszouten. De symbiose met de koraaldiertjes levert de zoöxanthellen een competitief voordeel op ten opzichte van algen die vrij in het water leven.
Drie gegevens over het rif zijn:
1 Koraaldiertjes produceren anorganische stofwisselingsproducten.
2 Algen produceren organische verbindingen.
3 Op het rif leeft de doornenkroon (een zeester) die zich voedt met koraaldiertjes.
4 In het water rond het rif leeft zoöplankton dat zich voedt met eencellige algen.$$, 'inline'),
  ('3502fb6b-2d7b-4eb1-a0a6-6aa56192f177', '3e27f270-ac9d-4261-8b68-f5dad72ffde5', $$sponzen zouden een sleutelrol spelen in de productiviteit van het koraalrif-ecosysteem$$,
   $$biologie-vwo-2021-iii-koraalverbleking-context4.png$$,
   $$De Nederlandse onderzoekers De Goeij en Van Oevelen veronderstelden dat bepaalde sponzen, die in holten tussen het koraal leven, een sleutelrol spelen in de hoge totale productiviteit van het koraalrif-ecosysteem.
Deze sponzen zouden de ‘mucus’ (slijm met opgeloste organische stoffen) die koraaldiertjes afgeven, opnemen en gebruiken voor de bouw van nieuwe sponscellen; oudere sponscellen worden afgestoten en vervolgens als detritus weer opgenomen door detritivoren (afvaleters).$$, 'inline'),
  ('70f74b2a-2b0b-49f2-9b8c-ae55c3d44a77', '3e27f270-ac9d-4261-8b68-f5dad72ffde5', $$experiment met 13C-verrijkte mucus om de route van organische stoffen aan te tonen$$,
   $$biologie-vwo-2021-iii-koraalverbleking-context5.png$$,
   $$Om hun verklaring voor de hoge totale productiviteit te onderzoeken sloten de onderzoekers enkele holten binnen het koraalrif af van het omringende water en injecteerden daarin mucus met organische stoffen verrijkt met 13C. Na zes uur werd de afsluiting ongedaan gemaakt, waarna gedurende twee dagen op verschillende momenten steeds een aantal metingen werd verricht. Met deze metingen wilden de onderzoekers het bestaan van de hierboven beschreven route van organische stoffen aantonen.$$, 'inline'),
  ('b4e6ecf4-7941-4dce-8827-6d6f5bc69133', '3e27f270-ac9d-4261-8b68-f5dad72ffde5', $$opname en omzetting van stikstofverbindingen bij normale en verhoogde temperatuur (afbeelding 2)$$,
   $$biologie-vwo-2021-iii-koraalverbleking-context6.png$$,
   $$Koraaldiertjes zijn ook gastheren voor andere symbionten, zoals bacteriën die een rol spelen in de stikstofkringloop. Als de temperatuur van het zeewater stijgt, wordt de groei van zoöxanthellen bevorderd.
In afbeelding 2 is weergegeven welke veranderingen in dat geval optreden bij de opname en omzetting van stikstofverbindingen in de koraaldiertjes met hun symbionten.$$, 'inline'),
  ('0b6c5729-53d8-4029-9dfa-0e56d6269486', '3e27f270-ac9d-4261-8b68-f5dad72ffde5', $$vier processen in de stikstofkringloop$$,
   $$biologie-vwo-2021-iii-koraalverbleking-context7.png$$,
   $$Enkele processen in de stikstofkringloop zijn:
1 nitrificatie
2 denitrificatie
3 stikstoffixatie
4 stikstofassimilatie$$, 'inline'),
  ('53505b9a-d606-4f98-a725-9662dd3821e6', '3e27f270-ac9d-4261-8b68-f5dad72ffde5', $$langdurige temperatuurstijging leidt tot bleaching door beschadiging van fotosynthese-enzymen$$,
   $$biologie-vwo-2021-iii-koraalverbleking-context8.png$$,
   $$De versnelde groei van de zoöxanthellen houdt geen stand. Langdurige stijging van de watertemperatuur leidt uiteindelijk tot verbleking (‘bleaching’) van het koraal: de zoöxanthellen verdwijnen, waardoor het witte kalkskelet van de koraaldiertjes zichtbaar wordt.
Er is onderzocht welke processen op cellulair niveau leiden tot bleaching. Een hogere watertemperatuur beschadigt enzymen die betrokken zijn bij de fotosynthese. Zo is op het thylakoïdmembraan de elektronentransportketen verstoord, waardoor verschillende schadelijke zuurstofverbindingen ontstaan.$$, 'inline'),
  ('5b71ba91-42d0-4f83-9dbe-0b8ff245cee2', '3e27f270-ac9d-4261-8b68-f5dad72ffde5', $$ook enzymen van de donkerreactie zijn beschadigd$$,
   $$biologie-vwo-2021-iii-koraalverbleking-context9.png$$,
   $$Ook enzymen van de donkerreactie zijn beschadigd.$$, 'inline'),
  ('275cd945-835b-4ff6-846d-4ef70c93ace0', '3e27f270-ac9d-4261-8b68-f5dad72ffde5', $$manieren waarop koraaldiertjes schadelijke zoöxanthellen verwijderen (afbeelding 3)$$,
   $$biologie-vwo-2021-iii-koraalverbleking-context10.png$$,
   $$De verstoring van de fotosynthese leidt tot een ophoping van schadelijke zuurstofverbindingen, zoals H2O2, waardoor de koraalcellen hun zoöxanthellen afstoten om celbeschadiging te voorkomen.
Er zijn verschillende manieren waarop koraaldiertjes hun schadelijke zoöxanthellen kunnen verwijderen (afbeelding 3). De afbeelding is niet compleet: de tekening laat nog niet zien hoe de exocytose van de symbiont (nummer 2) gaat.$$, 'inline'),
  ('4ff97857-dc2c-4813-a318-c41efa9a0370', '3e27f270-ac9d-4261-8b68-f5dad72ffde5', $$verschuiving naar temperatuurtolerante Symbiodinium-soorten als herstelmechanisme$$,
   $$biologie-vwo-2021-iii-koraalverbleking-context11.png$$,
   $$Het is niet duidelijk in hoeverre de verbleekte koraalriffen zich in de toekomst zullen herstellen. Een natuurlijk herstelmechanisme dat wordt waargenomen, is een verschuiving in de symbiose met de zoöxanthellen. Temperatuurgevoelige Symbiodinium-soorten worden vervangen door meer temperatuurtolerante Symbiodinium-soorten, waardoor de temperatuurtolerantie van het koraal 1 tot 1,5 ºC verschuift.
Sommige wetenschappers stellen dat deze aanpassing een vorm van evolutie is.$$, 'inline'),
  ('de65d617-7896-4461-99e5-1c0ed5bf9ce9', '2c20f12d-0dfc-4509-b45e-ee69f54247ae', $$antarctisch baarsje omringd door ijskristallen (afbeelding 1)$$,
   $$biologie-vwo-2021-iii-antivrieseiwitten-context1.png$$,
   $$De Amerikaanse onderzoeker Arthur DeVries ontdekte dat poolvissen aanpassingen hebben die voorkómen dat ze bevriezen in het ijskoude water. In afbeelding 1 is een antarctisch baarsje omringd door ijskristallen weergegeven.$$, 'inline'),
  ('84e0fe1d-0a38-472a-bab7-e34be932693a', '2c20f12d-0dfc-4509-b45e-ee69f54247ae', $$vissen rond Antarctica hebben antivrieseiwitten nodig om membraanschade door ijskristallen te voorkomen$$,
   $$biologie-vwo-2021-iii-antivrieseiwitten-context2.png$$,
   $$Rond Antarctica, waar de watertemperatuur gemiddeld -1,9 ºC is, vormen zich ijskristallen in het water. In dit ijskoude water zijn aangepaste vissen te vinden, met antivrieseiwitten in hun lichaam. Zonder deze antivrieseiwitten zouden in het lichaam van deze koudbloedige vissen ijskristallen ontstaan die schade aanrichten doordat ze membranen van cellen kapot prikken.$$, 'inline'),
  ('3c00576e-357d-465a-8dc3-b169d2a60901', '2c20f12d-0dfc-4509-b45e-ee69f54247ae', $$ijsvorming in het bloedplasma en osmotische problemen voor bloedcellen$$,
   $$biologie-vwo-2021-iii-antivrieseiwitten-context3.png$$,
   $$IJsvorming in het bloedplasma kan leiden tot osmotische problemen voor de bloedcellen, omdat ijskristallen veel minder zout bevatten dan vloeibaar water.$$, 'inline'),
  ('fc39d67c-1f9f-4ae4-97ea-4cd21a1c5082', '2c20f12d-0dfc-4509-b45e-ee69f54247ae', $$enkelvoudige bloedsomloop van een vis (afbeelding 2); ijskristallen ontstaan in de darmhaarvaten$$,
   $$biologie-vwo-2021-iii-antivrieseiwitten-context4.png$$,
   $$IJskristallen in de bloedsomloop blijven klein dankzij antivrieseiwitten. De kristalletjes accumuleren in de milt van de vis, waardoor schade aan de haarvaten beperkt wordt.
In afbeelding 2 is de enkelvoudige bloedsomloop van een vis vereenvoudigd weergegeven.
IJskristallen in het bloed ontstaan vooral in de haarvaten van het darmkanaal.$$, 'inline'),
  ('0111d15c-e195-45a5-b2c3-94ed1570c0fc', '2c20f12d-0dfc-4509-b45e-ee69f54247ae', $$vier bloedvaten van de vis$$,
   $$biologie-vwo-2021-iii-antivrieseiwitten-context5.png$$,
   $$Vier bloedvaten van de vis zijn:
1 haarvaten van de kieuwen
2 leverslagader
3 miltslagader
4 poortader$$, 'inline'),
  ('bd3bfa37-8758-4b7e-ae5a-e78b712d6f43', '2c20f12d-0dfc-4509-b45e-ee69f54247ae', $$werking van antivrieseiwitten tegen ijskristalgroei (afbeelding 3)$$,
   $$biologie-vwo-2021-iii-antivrieseiwitten-context6.png$$,
   $$Een ijskristal ontstaat meestal uit een zoutdeeltje en een paar watermoleculen. Het ijskristal groeit daarna doordat er steeds meer watermoleculen aan vasthechten. Antivrieseiwitten binden vermoedelijk aan de ijskristallen door de vorming van waterstofbruggen en verhinderen vervolgens de groei van het ijskristal. De mogelijke werking van antivrieseiwitten is schematisch weergegeven in afbeelding 3.
De werking van het antivrieseiwit in afbeelding 3 kan worden verklaard door de moleculaire eigenschappen van dit eiwit.$$, 'inline'),
  ('bd67d86e-6b79-4510-aa68-42856320e767', '2c20f12d-0dfc-4509-b45e-ee69f54247ae', $$antivrieseiwitten (AFGP''s) ontstonden stapsgewijs uit het trypsinogeen-gen$$,
   $$biologie-vwo-2021-iii-antivrieseiwitten-context7.png$$,
   $$Antivrieseiwitten (AFGP’s, van ‘antifreeze glycoprotein’) komen veel voor in poolvissen. AFGP’s worden gemaakt door de alvleesklier en worden afgegeven aan de darminhoud, waarna het ongebruikte deel van deze AFGP’s vanuit de darm wordt opgenomen in het bloed. Biologen uit de onderzoeksgroep van DeVries vermoeden dat het gen voor het antivrieseiwit stapsgewijs is ontstaan uit het trypsinogeen-gen.
Een kopie van het trypsinogeen-gen heeft eerst een aantal exonen verloren en vervolgens zijn de basen die coderen voor het aminozuurstukje Thr-Ala-Ala vele malen ingevoegd. Door deze veranderingen is in het nieuw gevormde AFGP-gen op een nieuwe plek een stopcodon ontstaan.$$, 'inline'),
  ('532216c3-027d-4898-828e-f9f1017affaa', '2c20f12d-0dfc-4509-b45e-ee69f54247ae', $$coderende streng van het AFGP-gen met stopcodon en het homologe deel van het trypsinogeen-gen (afbeelding 4)$$,
   $$biologie-vwo-2021-iii-antivrieseiwitten-context8.png$$,
   $$Een klein deel van de coderende streng van het AFGP-gen met daarin het stopcodon is weergegeven in afbeelding 4. Daaronder is het homologe (overeenkomstige) deel van het trypsinogeen-gen afgebeeld.
AFGP-gen: 5’ -….GGTGACACTGGCAGCCCTCTGGTGT….- 3’
trypsinogeen-gen: 5’ -….GGTGACTCCGGCAGCCCTCTGGTGT….- 3’$$, 'inline'),
  ('6c04e619-1cad-4126-9bd9-fe63eef41186', '2c20f12d-0dfc-4509-b45e-ee69f54247ae', $$AFGP-gen bevat code voor signaalpeptide dat de bestemming van het eiwit bepaalt$$,
   $$biologie-vwo-2021-iii-antivrieseiwitten-context9.png$$,
   $$Het AFGP-gen bevat ook de code voor een signaalpeptide. Een signaalpeptide bevindt zich aan het begin van de eiwitketen. Als de synthese van het eiwit aan de ribosomen is voltooid, bepaalt het signaalpeptide waar het eiwit terechtkomt. AFGP wordt uiteindelijk via exocytose uitgescheiden.$$, 'inline'),
  ('8f163f12-75ff-4018-b09b-ca32ec0bc80e', '2c20f12d-0dfc-4509-b45e-ee69f54247ae', $$trypsinogeen en AFGP komen beide in het darmkanaal terecht; trypsinogeen wordt omgezet in trypsine$$,
   $$biologie-vwo-2021-iii-antivrieseiwitten-context10.png$$,
   $$Zowel trypsinogeen als AFGP komt in het darmkanaal van de Antarctische vissen terecht. Trypsinogeen wordt in het darmkanaal omgezet in trypsine.$$, 'inline'),
  ('309135d7-ddcd-4e9e-8462-4757f9bba203', '2c20f12d-0dfc-4509-b45e-ee69f54247ae', $$antivrieseiwitten komen ook voor bij vissen in de noordelijke ijszeeën; vermoedelijk analoge ontwikkeling$$,
   $$biologie-vwo-2021-iii-antivrieseiwitten-context11.png$$,
   $$Antivrieseiwitten worden gevonden in vissen rondom de Zuidpool, maar ook bij vissen in de noordelijke ijszeeën. Onderzoekers nemen aan dat dit een analoge ontwikkeling is.$$, 'inline'),
  ('5451ce58-7e7c-49a5-bbff-262e2cf06462', 'd6131d76-6c51-4c40-b798-2397e620d30d', $$eerste baby met DNA van drie ouders geboren met behulp van een nieuwe conceptietechniek$$,
   $$biologie-vwo-2021-iii-baby-met-drie-ouders-context1.png$$,
   $$In 2016 werd ’s werelds eerste baby geboren met DNA van drie ouders. Het DNA was samengevoegd met behulp van een nieuwe conceptietechniek. Reden om deze techniek toe te passen was een afwijking in het mitochondriaal DNA van een vrouw met een kinderwens.$$, 'inline'),
  ('5b8759ac-a2d7-49f5-877c-ea833044f66d', 'd6131d76-6c51-4c40-b798-2397e620d30d', $$Maternal Spindle Transfer-techniek (MST) om mtDNA-schade te omzeilen (afbeelding 1)$$,
   $$biologie-vwo-2021-iii-baby-met-drie-ouders-context2.png$$,
   $$Stofwisselingsprocessen in mitochondria staan onder invloed van zowel kern-DNA als mitochondriaal DNA (mtDNA). Hoewel een mitochondrium slechts 37 genen bevat, zijn er behoorlijk wat stofwisselingsziekten die veroorzaakt worden door mutaties in dit mtDNA.
Bij de moeder van de drie-ouderbaby bevat een deel van de mitochondria sterk gemuteerd mtDNA. Zij heeft hier zelf geen hinder van, doordat niet alle mitochondria in haar cellen afwijkend zijn. Door de mtDNA-schade in haar eicellen is de kans klein om op natuurlijke wijze gezonde kinderen te krijgen. Daarom is voor de conceptie gebruikgemaakt van kunstmatige bevruchting met de zogenoemde Maternal Spindle Transfer-techniek (MST).
Bij MST wordt het kern-DNA van een eicel van de moeder samengevoegd met een kernloze eicel van een donor met normale mitochondria. Beide eicellen verkeren tijdens de overdracht van DNA in de laatste fase van de meiose. De hieruit geconstrueerde eicel wordt vervolgens kunstmatig bevrucht door een spermacel van de vader (afbeelding 1).$$, 'inline'),
  ('32f30024-83e4-4cd4-9c2d-ebef78cfe8a4', 'd6131d76-6c51-4c40-b798-2397e620d30d', $$mutatie in het ATP-synthase-gen (positie 8993) veroorzaakt de ziekte van Leigh$$,
   $$biologie-vwo-2021-iii-baby-met-drie-ouders-context3.png$$,
   $$De moeder van de drie-ouderbaby heeft een mutatie in het ATP-synthase-gen die de ziekte van Leigh veroorzaakt. Op positie 8993 is hier in de coderende streng van het mtDNA de oorspronkelijke stikstofbase vervangen door een andere. Daardoor wordt in de primaire structuur van de ATP-synthase een arginine ingebouwd in plaats van een leucine.$$, 'inline'),
  ('afccf969-e0a1-4ae0-a90d-df2c6b1b1c4d', 'd6131d76-6c51-4c40-b798-2397e620d30d', $$veel disfunctionele mitochondria geven problemen in hersenen, hart en spieren$$,
   $$biologie-vwo-2021-iii-baby-met-drie-ouders-context4.png$$,
   $$Als iemand relatief veel disfunctionele mitochondria heeft, leidt dat tot ernstige problemen in hersenen, hart en spieren.$$, 'inline'),
  ('c99b4ded-b118-49b6-9352-65fd0bf449ea', 'd6131d76-6c51-4c40-b798-2397e620d30d', $$mitochondria met gemuteerd mtDNA kunnen meeliften bij MST; toename van het percentage gemuteerd mtDNA in celkweken (afbeelding 2)$$,
   $$biologie-vwo-2021-iii-baby-met-drie-ouders-context5.png$$,
   $$Een probleem bij het toepassen van MST is dat mitochondria met gemuteerd mtDNA bij het overbrengen van de chromosomen kunnen meeliften uit de eicel. Hoewel de drie-ouderbaby minder dan 1% gemuteerd mtDNA heeft, kan het voor problemen zorgen als dit percentage tijdens de ontwikkeling van de baby toeneemt.
In-vitro-onderzoek met een groot aantal celkweken laat zien dat dit een reëel effect kan zijn. Bij een van de celkweken was na 40 celdelingen het percentage mitochondria met gemuteerd mtDNA toegenomen van 1% in de oorspronkelijke cel tot gemiddeld bijna 60% in de dochtercellen (afbeelding 2).$$, 'inline'),
  ('01713425-cd0f-4c2d-832c-cd4106853abe', 'd6131d76-6c51-4c40-b798-2397e620d30d', $$twee beweringen over het veranderen van het percentage gemuteerd mtDNA in de celkweek$$,
   $$biologie-vwo-2021-iii-baby-met-drie-ouders-context6.png$$,
   $$Over het veranderen van het percentage mitochondria met gemuteerd mtDNA in deze celkweek worden twee beweringen gedaan:
1 De genetische variatie in het mtDNA binnen deze celkweek wordt veroorzaakt door crossing-over.
2 Bij de toename en afname van het percentage gemuteerde mitochondria speelt toeval een rol.$$, 'inline'),
  ('bfff1b26-19d7-49d1-b708-138739970748', 'd6131d76-6c51-4c40-b798-2397e620d30d', $$leerling stelt dat gemuteerde mitochondria in een zygote geen probleem opleveren, gebaseerd op afbeelding 2$$,
   $$biologie-vwo-2021-iii-baby-met-drie-ouders-context7.png$$,
   $$Een leerling bestudeert de gegevens uit afbeelding 2.
Hij stelt dat gemuteerde mitochondria in een zygote geen probleem voor het kind zullen opleveren, omdat – hoewel na 40 celdelingen het percentage gemuteerde mitochondria hoog is – alle mitochondria na 60 celdelingen weer ‘gezond’ zijn.$$, 'inline'),
  ('29d6e4f8-7f19-4195-a59f-b01c0209ec17', 'd6131d76-6c51-4c40-b798-2397e620d30d', $$voorstel om de techniek alleen toe te passen voor de conceptie van jongens$$,
   $$biologie-vwo-2021-iii-baby-met-drie-ouders-context8.png$$,
   $$Vanwege onzekerheid over de ontwikkeling van het percentage disfunctionele mitochondria in drie-ouderbaby’s en de gevolgen die dat kan hebben voor de rest van hun leven, stellen sommige wetenschappers voor om de techniek alleen toe te passen voor de conceptie van jongens.$$, 'inline'),
  ('af2a65db-5fea-474d-99a8-0af8419b09af', '212473bd-6623-4c53-9c97-b32242e550b5', $$rijstopbrengst moet stijgen; C4-rijstproject wil C3-rijst ombouwen tot C4-rijst$$,
   $$biologie-vwo-2021-iii-het-c4-rijstproject-context1.png$$,
   $$Rijst is het basisvoedsel voor meer dan de helft van de wereldbevolking. Vanwege de groei van de wereldbevolking zou de rijstopbrengst tot 2050 met meer dan 50 procent moeten stijgen. In het C4-rijstproject probeert een internationaal samenwerkingsverband van wetenschappers een hogere opbrengst te realiseren door van de C3-rijstplant een C4-rijstplant te maken.$$, 'inline'),
  ('23c100a3-efe8-4eb8-85b0-f36252900708', '212473bd-6623-4c53-9c97-b32242e550b5', $$veredeling verhoogde de opbrengst van commerciële rijstrassen$$,
   $$biologie-vwo-2021-iii-het-c4-rijstproject-context2.png$$,
   $$Door veredeling is de opbrengst van de commerciële rijstrassen veel hoger dan die van de oorspronkelijke wilde rijst.$$, 'inline'),
  ('1891f95e-fd22-41ee-ac09-20496493a894', '212473bd-6623-4c53-9c97-b32242e550b5', $$Calvin-cyclus en fotorespiratie bij een C3-plant (afbeelding 1)$$,
   $$biologie-vwo-2021-iii-het-c4-rijstproject-context3.png$$,
   $$Rijst is, net als de meeste planten, een C3-plant. Dat houdt in dat bij de fotosynthese na de CO2-fixatie er een tussenproduct (PGA) ontstaat dat uit drie koolstof-atomen (C3) bestaat. Het rendement van dit proces wordt beperkt doordat het daarbij betrokken enzym rubisco niet alleen bindt aan CO2, maar ook aan O2. Naarmate de relatieve concentratie van zuurstof stijgt, neemt de affiniteit van rubisco voor zuurstof toe en wordt, behalve PGA (glycerinezuur-3-fosfaat), ook PG (glycolzuur-2-fosfaat) gevormd. In een proces dat fotorespiratie wordt genoemd, wordt hieruit weer PGA gevormd, dat in de Calvin-cyclus verwerkt kan worden.
In afbeelding 1 worden de Calvin-cyclus en de fotorespiratie schematisch weergegeven.$$, 'inline'),
  ('e09948ec-2c19-4c76-8ccb-a1406fc3fd8b', '212473bd-6623-4c53-9c97-b32242e550b5', $$hoge temperatuur sluit huidmondjes en verhoogt fotorespiratie, wat de fotosynthese-opbrengst halveert$$,
   $$biologie-vwo-2021-iii-het-c4-rijstproject-context4.png$$,
   $$Rijst wordt vooral verbouwd in de tropen. Bij een hoge omgevingstemperatuur sluiten de huidmondjes en neemt in het blad de fotorespiratie toe, waardoor het rendement van de fotosynthese in de plant kan halveren.$$, 'inline'),
  ('49a43db9-d20d-45ae-baac-bca01dabb9ad', '212473bd-6623-4c53-9c97-b32242e550b5', $$netto CO2-opname van een C3-plant tegen temperatuur bij twee CO2-concentraties (afbeelding 2)$$,
   $$biologie-vwo-2021-iii-het-c4-rijstproject-context5.png$$,
   $$Het verband tussen de netto CO2-opname van een C3-plant en de temperatuur bij twee verschillende CO2-concentraties is weergegeven in afbeelding 2.$$, 'inline'),
  ('ccdfa398-1eb6-4ef0-a2d6-2bfdeb9bd0ba', '212473bd-6623-4c53-9c97-b32242e550b5', $$drie beweringen over afbeelding 2$$,
   $$biologie-vwo-2021-iii-het-c4-rijstproject-context6.png$$,
   $$Over deze gegevens worden de volgende beweringen gedaan:
1 Bij 30 ºC is een CO2-concentratie van 330 ppm beperkend voor de fotosynthese.
2 Tussen de 30 en 35 ºC raken enzymen bij een CO2-concentratie van 330 ppm minder snel beschadigd dan bij 1000 ppm CO2.
3 Bij 30 ºC is de zuurstofafgifte van bladcellen bij 1000 ppm CO2 hoger dan bij 330 ppm CO2.$$, 'inline'),
  ('ad77bed3-4939-43b6-ae15-b547050e881a', '212473bd-6623-4c53-9c97-b32242e550b5', $$C4-mechanisme met PEPC voorkomt fotorespiratie; processen in parenchymcel en bundelschedecel (afbeelding 3)$$,
   $$biologie-vwo-2021-iii-het-c4-rijstproject-context7.png$$,
   $$In de loop van de evolutie is bij enkele groepen planten een mechanisme ontstaan om het optreden van fotorespiratie te vermijden door opgenomen CO2 vast te leggen in een C4-verbinding. Belangrijke C4-voedselgewassen zijn maïs en suikerriet. In C4-planten wordt fosfo-enolpyruvaat-decarboxylase (PEPC) gebruikt voor de fixatie van CO2. PEPC werkt sneller dan rubisco en heeft geen affiniteit voor zuurstof. Bij C4-planten zijn twee celtypen betrokken bij de fotosynthese: parenchymcellen en bundelschedecellen. In afbeelding 3 zijn processen van de fotosynthese in bladcellen van een C4-plant schematisch weergegeven.$$, 'inline'),
  ('7087269f-9aa9-4100-80b8-8ba04fa6f4da', '212473bd-6623-4c53-9c97-b32242e550b5', $$indeling C3/C4-planten gebaseerd op de eerste stabiele verbinding na CO2-fixatie$$,
   $$biologie-vwo-2021-iii-het-c4-rijstproject-context8.png$$,
   $$De indeling van C3- en C4-planten is gebaseerd op de eerste stabiele verbindingen die door fixatie van CO2 uit de lucht gevormd worden.$$, 'inline'),
  ('4ea44fa0-369e-4616-89e2-a1485070a9af', '212473bd-6623-4c53-9c97-b32242e550b5', $$bouw van bladeren van C3- en C4-planten: chloroplasten in bundelschedecellen (afbeelding 4)$$,
   $$biologie-vwo-2021-iii-het-c4-rijstproject-context9.png$$,
   $$Ook de bouw van de bladeren van C4-planten is aangepast. In C3-planten bevinden de chloroplasten zich nagenoeg alleen in parenchymcellen, maar in C4-planten bevatten ook de bundelschedecellen veel chloroplasten (afbeelding 4). Bundelschedecellen liggen rond de vaatbundels en de parenchymcellen liggen daar bij een C4-plant weer als een krans omheen. De buitenlaag van de bundelschede bevat kurkstof om diffusie van CO2 te voorkomen.$$, 'inline'),
  ('5b6e69b0-7e3b-4a55-9243-49a72310e863', '212473bd-6623-4c53-9c97-b32242e550b5', $$chloroplasten in bundelschedecellen bevatten geen fotosysteem II$$,
   $$biologie-vwo-2021-iii-het-c4-rijstproject-context10.png$$,
   $$De chloroplasten in de bundelschedecellen bevatten geen fotosysteem II in de thylakoïden.$$, 'inline'),
  ('2bbcd5d8-be82-4d1d-b01a-4e33f8e3b407', '212473bd-6623-4c53-9c97-b32242e550b5', $$stappenplan naar C4-rijst: anatomische en biochemische veranderingen plus optimalisatie (afbeelding 5)$$,
   $$biologie-vwo-2021-iii-het-c4-rijstproject-context11.png$$,
   $$De groep wetenschappers wil rijst omvormen tot een C4-plant. In de loop van de evolutie is C4-fotosynthese vele malen onafhankelijk ontstaan, hetgeen er volgens de onderzoekers op wijst dat de stap van C3 naar C4 niet al te moeilijk is.
In afbeelding 5 is een globaal stappenplan weergegeven dat moet leiden tot C4-rijst.$$, 'inline'),
  ('cece2825-ac3b-451a-8854-d97bf8fcf5fc', '212473bd-6623-4c53-9c97-b32242e550b5', $$verschillen in bladweefsel tussen rijstmutanten$$,
   $$biologie-vwo-2021-iii-het-c4-rijstproject-context12.png$$,
   $$De anatomische veranderingen in het stappenplan betreffen vooral de bouw van het blad. De onderzoekers maakten talrijke rijstmutanten en selecteerden daaruit de meest veelbelovende planten om de gunstige eigenschappen door gericht kruisen te stapelen.
Verschillen in het bladweefsel van de verschillende rijstmutanten waren:
1 meer of minder vaatbundels per bladoppervlak
2 meer of minder bundelschedecellen om de vaatbundels
3 meer of minder chloroplasten in bundelschedecellen$$, 'inline'),
  ('449363cb-54dd-4535-92e2-f0788efcc383', '212473bd-6623-4c53-9c97-b32242e550b5', $$biochemische veranderingen betreffen regulatie van genexpressie; drie factoren$$,
   $$biologie-vwo-2021-iii-het-c4-rijstproject-context13.png$$,
   $$De biochemische veranderingen in het stappenplan (afbeelding 5) hebben vooral betrekking op enzymen. Gebleken is dat veel enzymen van de C4-fotosynthese wel vóórkomen in C3-planten, maar op andere plaatsen. Het onderzoek richt zich daarom op regulatie van de genexpressie.
Enkele factoren die genexpressie reguleren zijn:
1 aanwezigheid van activators
2 methylering van het DNA
3 RNA-interferentie$$, 'inline'),
  ('63d7a5c4-7b6e-4e88-a7af-723fee8672f2', '212473bd-6623-4c53-9c97-b32242e550b5', $$C4-rijst vóór 2040 en duurzamer door efficiënter landgebruik; drie eigenschappen$$,
   $$biologie-vwo-2021-iii-het-c4-rijstproject-context14.png$$,
   $$De onderzoekers zijn ervan overtuigd dat het ombouwen van C3- naar C4-rijst zal lukken vóór 2040. Zij noemen als voordeel dat de teelt van C4-rijst ecologisch duurzamer is dan de teelt van C3-rijst omdat het leidt tot een efficiënter gebruik van land, stikstof (mest) en water.
Eigenschappen van C4-rijst vergeleken met C3-rijst zijn:
1 De fotosynthesesnelheid blijft langer toenemen bij toenemende lichtintensiteit.
2 Er is minder rubisco nodig.
3 Bij deels gesloten huidmondjes is er meer diffusie van CO2.$$, 'inline'),
  ('41e2697f-66c8-4b9a-80cb-de576ff14b09', 'febe07e3-7f78-413b-b401-05731d3e1433', $$Peppelenbosch onderzoekt zweepwormen voor het toedienen van medicatie bij de ziekte van Crohn$$,
   $$biologie-vwo-2021-iii-gemodificeerde-zweepwormen-tegen-de-ziekte-van-crohn-context1.png$$,
   $$In Nederland zijn er waarschijnlijk meer dan vijftigduizend patiënten met de ziekte van Crohn. De behandeling bestaat voornamelijk uit symptoombestrijding en heeft wisselend resultaat. De Nederlandse hoogleraar Maikel Peppelenbosch onderzoekt het gebruik van zweepwormen voor het toedienen van medicatie.$$, 'inline'),
  ('128f1bd3-bfcc-4d3e-9d17-acf937df7189', 'febe07e3-7f78-413b-b401-05731d3e1433', $$ziekte van Crohn: chronische ontstekingsziekte van de darm, beïnvloed door erfelijkheid, omgeving en darmbioom$$,
   $$biologie-vwo-2021-iii-gemodificeerde-zweepwormen-tegen-de-ziekte-van-crohn-context2.png$$,
   $$De ziekte van Crohn is een chronische ontstekingsziekte van de darm. Erfelijkheid en omgevingsfactoren beïnvloeden de kans dat iemand de ziekte krijgt. Ook het darmbioom – het totaal aan micro-organismen in de darm – lijkt een rol te spelen.
De ontstekingen ontstaan door sterke afweerreacties in het spijsverteringskanaal. Door de ontstekingen beschadigt het darmepitheel.$$, 'inline'),
  ('58d5653a-6c6a-4b4e-8e58-8bbff677d148', 'febe07e3-7f78-413b-b401-05731d3e1433', $$werking van membraaneiwitten van darmepitheelcellen in een darmvlok (afbeelding 1)$$,
   $$biologie-vwo-2021-iii-gemodificeerde-zweepwormen-tegen-de-ziekte-van-crohn-context3.png$$,
   $$Een van de symptomen van de ziekte is vermoeidheid. De oorzaak is mogelijk een vermindering van het aantal darmvlokken in de dunne darm door de ontstekingen.
In afbeelding 1 is de werking van verschillende typen membraaneiwitten van darmepitheelcellen in een darmvlok vereenvoudigd weergegeven.$$, 'inline'),
  ('9112cd36-95bd-4725-ae6e-7b5c54b40fa6', 'febe07e3-7f78-413b-b401-05731d3e1433', $$afweersysteem in de darmen tolereert mutualisten en commensalen; IL-10 stuurt T-helpercel-differentiatie$$,
   $$biologie-vwo-2021-iii-gemodificeerde-zweepwormen-tegen-de-ziekte-van-crohn-context4.png$$,
   $$Het afweersysteem in de darmen wijkt af van dat in het interne milieu, omdat niet alle bacteriën er bestreden worden: de mutualisten en commensalen in het microbioom worden getolereerd. Hierbij lijkt de productie van de ontstekingsremmende mediator IL-10 een cruciale rol te spelen.
IL-10 wordt afgegeven door macrofagen in de darmwand en stuurt de differentiatie van geactiveerde T-helpercellen in een bepaalde richting.$$, 'inline'),
  ('d7028054-85f5-40ee-b602-229e30f9ee7a', 'febe07e3-7f78-413b-b401-05731d3e1433', $$differentiatie van T-helpercellen (afbeelding 2)$$,
   $$biologie-vwo-2021-iii-gemodificeerde-zweepwormen-tegen-de-ziekte-van-crohn-context5.png$$,
   $$De differentiatie van T-helpercellen is weergegeven in afbeelding 2.$$, 'inline'),
  ('c9d52ce6-6593-4035-a0b6-59dc22459a06', 'febe07e3-7f78-413b-b401-05731d3e1433', $$Crohn-patiënten maken minder IL-10 aan en hebben een lagere microbiële biodiversiteit$$,
   $$biologie-vwo-2021-iii-gemodificeerde-zweepwormen-tegen-de-ziekte-van-crohn-context6.png$$,
   $$Patiënten met de ziekte van Crohn maken minder IL-10 aan en hun microbioom heeft een andere samenstelling dan dat van gezonde mensen. De biodiversiteit is lager: er zijn relatief minder goedaardige bacteriesoorten in de darmen.
Deze lage biodiversiteit zou het gevolg kunnen zijn van de ziekte van Crohn, maar het zou ook juist de oorzaak ervan kunnen zijn.$$, 'inline'),
  ('7118e05d-b232-4579-a68e-deca61f4baaa', 'febe07e3-7f78-413b-b401-05731d3e1433', $$de ziekte van Crohn is niet te genezen; medicatie onderdrukt symptomen, waaronder een van een hormoon afgeleid middel$$,
   $$biologie-vwo-2021-iii-gemodificeerde-zweepwormen-tegen-de-ziekte-van-crohn-context7.png$$,
   $$De ziekte van Crohn is tot nu toe niet te genezen. Medicatie richt zich voornamelijk op het onderdrukken van de symptomen.
Een van de gebruikte medicijnen is afgeleid van een hormoon.$$, 'inline'),
  ('413f10a1-bdb8-4a68-8ebb-d6edac9b134a', 'febe07e3-7f78-413b-b401-05731d3e1433', $$Engelse onderzoeksgroep (2007): darmbacterie die bij xylaan-inname TGFβ produceert, gestrand door kankerrisico$$,
   $$biologie-vwo-2021-iii-gemodificeerde-zweepwormen-tegen-de-ziekte-van-crohn-context8.png$$,
   $$In 2007 kwam een Engelse onderzoeksgroep met een experimentele methode om patiënten met de ziekte van Crohn te behandelen. De onderzoekers maakten gebruik van het menselijke TGFβ-gen, dat codeert voor een groeifactor die darmcellen tot delen aanzet en de productie van de ontstekingsremmer IL-10 door macrofagen stimuleert.
Door genetische modificatie construeerden zij een darmbacterie die TGFβ produceert wanneer het voor mensen onverteerbare koolhydraat xylaan als voedingsbron wordt aangeboden. De behandeling werkt dan als volgt: nadat de bacteriën de darm van een patiënt gekoloniseerd hebben, kan een drankje met xylaan helpen de ontstekingen te onderdrukken.
Deze bacteriële medicatie is in een experimenteel stadium gestrand. Door mutatie van de regulerende sequenties zou een variant kunnen ontstaan die de kans op het ontstaan van darmkanker vergroot.$$, 'inline'),
  ('b0044671-49a4-41ba-9ba5-03c298e92fe3', 'febe07e3-7f78-413b-b401-05731d3e1433', $$Peppelenbosch wil zweepwormen (Trichuris suis) voorzien van het menselijke IL-10-gen$$,
   $$biologie-vwo-2021-iii-gemodificeerde-zweepwormen-tegen-de-ziekte-van-crohn-context9.png$$,
   $$Maikel Peppelenbosch stelt een alternatieve strategie voor, met gemodificeerde zweepwormen van de soort Trichuris suis. Deze soort komt in varkensdarmen voor, maar kan ook enkele maanden in het darmkanaal van de mens overleven. Peppelenbosch wil zweepwormen met DNA-technieken voorzien van het menselijke IL-10-gen en daarna inbrengen in het darmkanaal van patiënten met de ziekte van Crohn. De afgifte van IL-10 door deze zweepwormen zou een gunstig effect moeten hebben op de patiënten met de ziekte van Crohn.$$, 'inline'),
  ('527a8b35-dda0-4843-9e23-7deaae804a39', 'febe07e3-7f78-413b-b401-05731d3e1433', $$extra barrière zorgt dat het IL-10-gen alleen in zweepwormen tot expressie komt, nooit in bacteriën, dankzij ontbrekende splicing$$,
   $$biologie-vwo-2021-iii-gemodificeerde-zweepwormen-tegen-de-ziekte-van-crohn-context10.png$$,
   $$Om het succes van zijn onderzoek te vergroten, sluit Peppelenbosch zoveel mogelijk risico’s uit. Hoewel uitwisseling van DNA tussen eukaryoten en bacteriën in principe niet optreedt, bouwt hij toch een extra barrière in zodat het gen wel in zweepwormen tot de productie van werkzaam IL-10 leidt, maar nooit in bacteriën. Hij maakt daarbij gebruik van het feit dat bacteriën geen splicing uitvoeren.$$, 'inline'),
  ('3e518d8a-f7ef-4476-85e8-d8d400404eee', 'febe07e3-7f78-413b-b401-05731d3e1433', $$vier categorieën waarop geldverstrekkende organisaties onderzoeksaanvragen beoordelen$$,
   $$biologie-vwo-2021-iii-gemodificeerde-zweepwormen-tegen-de-ziekte-van-crohn-context11.png$$,
   $$Onderzoeksaanvragen worden beoordeeld door geldverstrekkende organisaties. Zij letten daarbij ook op de impact van de studie op de behandeling van de patiënten. Daarbij is onderscheid te maken tussen:
1 fundamentele kennis over oorzaken van de ziekte
2 informatie over de aard en het verloop van de ziekte, waardoor de behandeling gepersonaliseerd zou kunnen worden
3 behandelingsmethoden die de symptomen van de ziekte bestrijden
4 behandelingsmethoden die de ziekte genezen$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('9aa23c74-984b-4ffd-a934-fc58467f9746', '3e27f270-ac9d-4261-8b68-f5dad72ffde5', 1,
   '[{"domain": "Molecuul- en Celniveau", "subdomain": "Stofwisseling van de cel"}]'::jsonb,
   '["symbiose", "fotosynthese", "lichtintensiteit", "zoöxanthellen"]'::jsonb,
   $$Verklaren waarom koraaldiertjes die in symbiose leven met zoöxanthellen niet dieper dan een bepaalde diepte kunnen voorkomen.$$,
   $$biologie-vwo-2021-iii-koraalverbleking-vraag1.png$$, $$2p 1 Leg uit waardoor koraaldiertjes die in symbiose leven met zoöxanthellen, niet dieper voor kunnen komen.$$, array['6d98526f-969c-4966-a8b6-f8773f2679d9', 'c489d403-5f48-4a68-ad26-b77eacfaa26e']::uuid[]),
  ('53053c7c-3b96-44d8-b9f7-e8434935c972', '3e27f270-ac9d-4261-8b68-f5dad72ffde5', 2,
   '[{"domain": "Populatie- en ecosysteemniveau", "subdomain": "Interactie in ecosystemen"}]'::jsonb,
   '["symbiose", "competitief voordeel", "mutualisme", "voedingsstoffen"]'::jsonb,
   $$Beoordelen welke gegevens over het koraalrif een competitief voordeel opleveren voor zoöxanthellen ten opzichte van vrij levende algen.$$,
   $$biologie-vwo-2021-iii-koraalverbleking-vraag2.png$$, $$2p 2 Noteer de nummers 1 tot en met 4 onder elkaar op je antwoordblad en schrijf erachter of het betreffende gegeven wel of geen competitief voordeel oplevert voor de zoöxanthellen ten opzichte van vrij levende algen.$$, array['c8755f54-b6e1-45c7-98e2-6edd86c11539']::uuid[]),
  ('c26948f9-2215-4598-a3c0-78f601b9ce18', '3e27f270-ac9d-4261-8b68-f5dad72ffde5', 3,
   '[{"domain": "Populatie- en ecosysteemniveau", "subdomain": "Regulatie van ecosystemen"}]'::jsonb,
   '["isotopenlabeling", "experimenteel ontwerp", "energiestroom", "detritivoren"]'::jsonb,
   $$Bepalen welke metingen nodig zijn en welke resultaten de veronderstelde route van organische stoffen van koraaldiertje naar spons bevestigen.$$,
   $$biologie-vwo-2021-iii-koraalverbleking-vraag3.png$$, $$2p 3 − Noteer welke metingen moesten worden gedaan.
− Beschrijf welke resultaten het bestaan van deze route bevestigen.$$, array['3502fb6b-2d7b-4eb1-a0a6-6aa56192f177', '70f74b2a-2b0b-49f2-9b8c-ae55c3d44a77']::uuid[]),
  ('b3ae4aa8-c98f-4a9d-a5d4-8fb52850b6e1', '3e27f270-ac9d-4261-8b68-f5dad72ffde5', 4,
   '[{"domain": "Populatie- en ecosysteemniveau", "subdomain": "Regulatie van ecosystemen"}]'::jsonb,
   '["voedselweb", "trofisch niveau", "consument", "reducent", "detritus"]'::jsonb,
   $$Bepalen welke trofische rol(len) sponzen vervullen in het voedselweb van het koraalrif.$$,
   $$biologie-vwo-2021-iii-koraalverbleking-vraag4.png$$, $$2p 4 Welke rol hebben de sponzen in het voedselweb op basis van de gegevens over het koraalrif?
A alleen consument van de 1e orde en hoger
B alleen consument van de 2e orde en hoger
C alleen consument van de 1e orde en producent
D alleen consument van de 2e orde en producent
E alleen consument van de 1e orde en reducent
F alleen consument van de 2e orde en reducent$$, array['c8755f54-b6e1-45c7-98e2-6edd86c11539', '3502fb6b-2d7b-4eb1-a0a6-6aa56192f177', '70f74b2a-2b0b-49f2-9b8c-ae55c3d44a77']::uuid[]),
  ('0f708bde-2f60-416e-bd2d-9dfd2c9344c5', '3e27f270-ac9d-4261-8b68-f5dad72ffde5', 5,
   '[{"domain": "Populatie- en ecosysteemniveau", "subdomain": "Regulatie van ecosystemen"}]'::jsonb,
   '["stikstofkringloop", "nitrificatie", "denitrificatie", "stikstoffixatie", "stikstofassimilatie"]'::jsonb,
   $$Beoordelen welke processen van de stikstofkringloop toenemen in koraaldiertjes met hun symbionten bij een stijgende watertemperatuur.$$,
   $$biologie-vwo-2021-iii-koraalverbleking-vraag5.png$$, $$2p 5 Noteer de nummers 1 tot en met 4 onder elkaar op je antwoordblad en schrijf erachter of het proces wel of niet toeneemt in koraaldiertjes met hun symbionten als de watertemperatuur stijgt.$$, array['b4e6ecf4-7941-4dce-8827-6d6f5bc69133', '0b6c5729-53d8-4029-9dfa-0e56d6269486']::uuid[]),
  ('f66fe067-d197-4cb9-81d4-cc6dfce239f6', '3e27f270-ac9d-4261-8b68-f5dad72ffde5', 6,
   '[{"domain": "Molecuul- en Celniveau", "subdomain": "Stofwisseling van de cel"}]'::jsonb,
   '["lichtreactie", "fotosysteem", "elektronentransportketen", "NADPH"]'::jsonb,
   $$Benoemen in welke verbinding een elektron uit de lichtreactie van de fotosynthese na transport via fotosysteem II en I terechtkomt.$$,
   $$biologie-vwo-2021-iii-koraalverbleking-vraag6.png$$, $$1p 6 In welke verbinding komt een elektron dat via fotosysteem II en I getransporteerd wordt terecht onder normale omstandigheden?
A in ATP
B in H2O
C in NADPH
D in O2$$, array['53505b9a-d606-4f98-a725-9662dd3821e6']::uuid[]),
  ('a0076130-d67b-4aa4-a6b5-9ecc9dafd95a', '3e27f270-ac9d-4261-8b68-f5dad72ffde5', 7,
   '[{"domain": "Molecuul- en Celniveau", "subdomain": "Stofwisseling van de cel"}]'::jsonb,
